(function(root){
  'use strict';
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const labels={correct:'Richtig',partial:'Teilweise richtig',incorrect:'Noch üben',unclear:'Nachprüfen'};
  const questionCount=n=>n+' '+(n===1?'Frage':'Fragen');
  function steps(active){return `<ol class="flow-steps" aria-label="Dein Lernablauf">${['Fragen lernen','Test machen','Gezielt festigen'].map((text,i)=>`<li class="${i===active?'current':i<active?'finished':''}" ${i===active?'aria-current="step"':''}><b>${i<active?'✓':i+1}</b><span>${text}</span></li>`).join('')}</ol>`;}
  function hub({state,cards,ai,button,icon,heading}){
    const F=root.LernpassFlow,C=root.LernpassCore,f=F.flow(state),u=F.unit(state,f.activeUnitId),t=F.test(state,f.activeTestId),pool=Object.keys(f.pool),unfinished=t&&t.status!=='complete';
    return `${heading('LERNEN MIT EINEM KLAREN ABLAUF','Erst verstehen.<br>Dann <em>selbst erklären.</em>','Lerne die Fragen deiner Einheit mit Antworten. Prüfe dich danach in einem Test und festige gezielt deine Lücken.')}${steps(0)}<section class="panel knowledge-feature"><div><span class="eyebrow">DEIN GESAMTES GELERNTES WISSEN</span><h2>Was bleibt ohne Vorlage?</h2><p>${F.learnedIds(state,cards).length} gelernte Fragen zufällig gemischt. Auch nur Text- oder Bildfragen sind möglich. Jeder Test lässt sich pausieren.</p></div><div class="button-row">${button('knowledge-test','Wissen testen','button primary')}${button('visual-catalog','Bild- & Skizzenfragen lernen','button secondary')}</div></section><section class="unit-hub-grid"><article class="panel unit-feature"><span class="soft-icon green">${icon('learn')}</span><div class="eyebrow">DEINE NÄCHSTE LERNEINHEIT</div><h2>${u&&!u.completed?'Mach dort weiter,<br>wo du aufgehört hast.':'Kleine Einheit. <br>Großer Zusammenhang.'}</h2><p>${u&&!u.completed?`${u.studied.length} von ${questionCount(u.ids.length)} gelesen. Deine Erklärungen und die restlichen Fragen warten auf dich.`:`Bis zu ${state.plan.session} Fragen aus deinem Tagesplan – mit verständlichen Antworten, Merksätzen und Beispielen.`}</p><div class="unit-feature-meta"><span>${icon('catalog')} ${questionCount(u&&!u.completed?u.ids.length:Math.min(state.plan.session,Math.max(1,C.dailyQueue(cards,state).length)))}</span><span>${icon('clock')} In deinem Tempo</span></div>${button(u&&!u.completed?'unit-resume':'unit-start',u&&!u.completed?'Einheit fortsetzen '+icon('arrow'):'Lerneinheit starten '+icon('arrow'),'button primary',u&&!u.completed?`data-id="${esc(u.id)}"`:'')}${u?.completed?button('unit-resume','Letzte Einheit & Test öffnen','text-link',`data-id="${esc(u.id)}"`):''}</article><div class="unit-side-stack"><article class="panel unit-next"><span class="tiny-label">02 · WISSEN ANWENDEN</span><h2>${unfinished?'Dein Test ist gespeichert.':'Bereit für den Test?'}</h2><p>${unfinished?`${questionCount(t.ids.length)} · ${t.status==='draft'?'Du kannst deine Antworten weiter bearbeiten.':'Deine Antworten warten auf die vollständige Bewertung.'}`:'Nach jeder gelernten Einheit kannst du frei antworten. Die KI prüft deine Fachpunkte nach der Abgabe.'}</p>${unfinished?button('test-open','Test fortsetzen '+icon('arrow'),'button secondary',`data-id="${esc(t.id)}"`):u?.completed?button('unit-test','Test zur letzten Einheit '+icon('arrow'),'button secondary',`data-id="${esc(u.id)}"`):'<span class="small-muted">Wird nach deiner ersten Lerneinheit verfügbar.</span>'}</article><article class="panel unit-next"><span class="tiny-label">03 · DEIN WIEDERHOLUNGSPOOL</span><h2>${pool.length} ${pool.length===1?'Frage zum':'Fragen zum'} Festigen</h2><p>Falsche, unvollständige und unklare Antworten bleiben hier. Sie tauchen zufällig in späteren Tests auf. Gelegentlich kommt auch eine bereits richtig gelernte Kontrollfrage dazu.</p>${pool.length?button('repeat-test','Wiederholungen testen '+icon('arrow'),'text-link'):'<span class="small-muted">Füllt sich automatisch mit deinen Testergebnissen.</span>'}</article></div></section>${!ai.configured?'<div class="notice warning">KI ist optional. Du kannst lernen, Tests beantworten und mit den Fachpunkten selbst vergleichen. Für automatische Textbewertungen kannst du deinen eigenen API-Schlüssel verbinden.</div>':''}${root.LernpassInsights.render({state,cards,button,icon})}${pool.length?`<section class="panel repeat-panel"><div class="section-top"><div><div class="eyebrow">AUS DEINEN TESTS GESAMMELT</div><h2>Diese Fragen kommen wieder.</h2></div>${button('pool-learn','Erklärungen lernen '+icon('arrow'),'text-link')}</div><p>Vollständig richtig beantwortete Fragen verlassen den Pool automatisch. „Nachprüfen“ bedeutet, dass die KI keine sichere Bewertung geben konnte.</p><div class="repeat-list">${pool.slice(0,6).map(id=>{const c=cards.find(c=>c.id===id);return `<div><span class="case-id">${id}</span><strong>${esc(c.title)}</strong><span class="result-tag ${f.pool[id].verdict}">${labels[f.pool[id].verdict]}</span></div>`;}).join('')}</div>${pool.length>6?`<details class="pool-more"><summary>Weitere ${pool.length-6} Fragen anzeigen</summary><div class="repeat-list">${pool.slice(6).map(id=>`<div><span class="case-id">${id}</span><strong>${esc(cards.find(c=>c.id===id).title)}</strong><span class="result-tag ${f.pool[id].verdict}">${labels[f.pool[id].verdict]}</span></div>`).join('')}</div></details>`:''}</section>`:''}${f.tests.length?`<section class="panel test-history"><div class="section-top"><div><div class="eyebrow">AUF DIESEM GERÄT GESPEICHERT</div><h2>Deine letzten Tests</h2></div></div>${[...f.tests].reverse().map(test=>{const s=F.summary(test);return `<button class="test-history-row" data-action="test-open" data-id="${esc(test.id)}"><span class="soft-icon">${icon(test.status==='complete'?'check':'clock')}</span><span><strong>${test.kind==='knowledge'?'Wissenstest':test.kind==='quick'?'Kurztest':test.unitId?'Test zur Lerneinheit':'Wiederholungstest'}</strong><small>${new Date(test.day+'T12:00:00').toLocaleDateString('de-AT')} · ${questionCount(s.total)}</small></span><span>${test.status==='draft'?'Entwurf':s.pending?`${s.total-s.pending}/${s.total} bewertet`:`${s.correct}/${s.total} richtig`}</span>${icon('arrow')}</button>`;}).join('')}</section>`:''}<details class="extra-practice"><summary>Weitere Übungsformen</summary><div class="learning-options compact-options">${[['due','clock','Karteikarten wiederholen','Fällige Karten mit eigener Einschätzung.'],['start-write','learn','Einzelne freie Antworten','Eine Erklärung schreiben und sofort prüfen.'],['start-speak','talk','Laut erklären','Ohne Test in deinem Tempo sprechen.']].map(([action,i,title,text])=>`<button class="option-card panel" data-action="${action}"><span class="option-icon">${icon(i)}</span><h2>${title}</h2><p>${text}</p></button>`).join('')}</div></details>`;
  }
  function unitPage({unit:u,cards,view,button,icon,answerHTML}){
    const done=u.completed&&!view.reread;
    const top=`<div class="session-top">${button('flow-hub',icon('back')+' Alle Lerneinheiten','link-button')}<span>DEINE LERNEINHEIT</span><b>${u.studied.length} / ${u.ids.length} gelesen</b></div>${steps(done?1:0)}`;
    if(done)return `${top}<section class="panel unit-complete"><span class="success-icon">${icon('check')}</span><div class="eyebrow">DIE GRUNDLAGE IST GELEGT</div><h1>Jetzt gehört das Wort <em>dir.</em></h1><p>Du hast ${u.ids.length===1?"die Frage":"alle "+questionCount(u.ids.length)} dieser Einheit gelesen. Wenn du bereit bist, erkläre die Antworten ohne Vorlage in einem Test.</p><div class="unit-topic-tags">${u.ids.map(id=>`<span class="tag">${id} · ${esc(cards.find(c=>c.id===id).title)}</span>`).join('')}</div><div class="button-row">${button('unit-test','Jetzt Test starten '+icon('arrow'),'button primary',`data-id="${esc(u.id)}"`)}${button('unit-reread','Noch einmal durchlesen','button secondary',`data-id="${esc(u.id)}"`)}</div><small>Die Testreihenfolge wird neu gemischt. Frühere Fehler und gelegentlich eine schon richtig gelernte Kontrollfrage kommen dazu. Lesen allein erhöht keine Erinnerungsstufe.</small></section>`;
    const card=cards.find(c=>c.id===u.ids[u.position]),read=u.studied.includes(card.id);
    return `${top}<div class="unit-question-nav" aria-label="Fragen dieser Einheit">${u.ids.map((id,i)=>button('unit-position',`${u.studied.includes(id)?'✓ ':''}${id}`,'unit-question-chip '+(i===u.position?'active':''),`data-position="${i}" aria-label="Frage ${id}${u.studied.includes(id)?', gelesen':''}" ${i===u.position?'aria-current="true"':''}`)).join('')}</div><div class="session-counter">Frage ${u.position+1} von ${u.ids.length} <span>· ${read?'Bereits gelesen':'Erklärung kennenlernen'}</span></div><article class="study-card panel unit-reading"><div class="card-labels"><span class="case-id">${card.id}</span><span class="tag">${esc(card.category)}</span><span class="writing-tag">${icon('catalog')} LERNEN</span></div><h1>${esc(card.title)}</h1><p class="study-question">${esc(card.question)}</p><div class="reading-intro">${icon('spark')}<span>Lies die Erklärung in Ruhe. Stell dir danach vor, wie du sie jemandem in der Werkstatt erklären würdest.</span></div>${answerHTML(card)}</article><div class="unit-reading-footer"><div>${button('unit-prev',icon('back')+' Zurück','button secondary',u.position===0?'disabled':'')}</div>${button('unit-studied',u.position===u.ids.length-1?'Gelesen · Einheit abschließen '+icon('check'):'Gelesen · nächste Frage '+icon('arrow'),'button primary')}</div>`;
  }
  function testPage({test:t,state,cards,button,icon,drawings,ai,busy,error,answerHTML}){
    const F=root.LernpassFlow,Q=root.LernpassWorkbook,s=F.summary(t),visual=c=>Q?Q.isVisual(c):Boolean(c.imagePage),byId=id=>cards.find(c=>c.id===id),manualPending=t.ids.filter(id=>(visual(byId(id))||!ai.configured)&&!t.entries[id].assessment).length,textPending=s.pending-manualPending;
    const top=`<div class="session-top">${button('flow-hub',icon('back')+' Speichern & zurück','link-button')}<span>${t.kind==='knowledge'?'WISSENSTEST · ALLE GELERNTEN FRAGEN':t.kind==='quick'?'KURZTEST · BEKANNTE FRAGEN':t.unitId?'TEST ZUR LERNEINHEIT':'WIEDERHOLUNGSTEST'}</span><b>Automatisch gespeichert</b></div>${steps(t.status==='draft'?1:2)}`;
    if(t.status==='draft'){
      const id=t.ids[t.position],card=byId(id),entry=t.entries[id],answered=t.ids.filter(q=>t.entries[q].answer.trim()).length,isVisual=visual(card);
      return `${top}<div class="session-track"><i style="width:${answered/t.ids.length*100}%"></i></div><div class="session-counter">Frage ${t.position+1} von ${t.ids.length}<span id="testAnswered"> · ${answered} Antworten gespeichert${s.repeats?' · '+s.repeats+' Wiederholungen':''}${s.controls?' · 1 Kontrollfrage':''}</span></div><article class="study-card panel test-writing"><div class="card-labels"><span class="case-id">${id}</span><span class="tag">${esc(card.category)}</span>${entry.source==='repeat'?'<span class="result-tag partial">Wiederholungsfrage</span>':entry.source==='control'?'<span class="result-tag correct">Kontrollfrage</span>':''}${isVisual?'<span class="visual-badge">Bild / Skizze · eigener Vergleich</span>':''}</div><h1>${esc(card.title)}</h1><p class="study-question">${esc(card.question)}</p>${isVisual?`${isVisual?(Q?.visualNote(card)||''):'<div class="visual-note"><b>Ohne API · dein eigener Vergleich</b><span>Lies deine Antwort, decke dann die Fachpunkte auf und schätze deinen Wissensstand ehrlich ein. Keine KI-Bewertung.</span></div>'}<div class="recall-drawing">${isVisual?drawings(card):''}</div><p class="small-muted">Präge dir die Vorlage ein. Verberge sie und zeichne oder erkläre aus dem Gedächtnis auf Papier. Deine Bilder im eigenen Katalog werden erst nach der Abgabe zum Vergleich angezeigt.</p>`:''}<label class="field-label" for="testAnswer">${isVisual?'Deine Erklärung / Skizzennotizen':'Deine Antwort in eigenen Worten'}<span>Die Musterantwort bleibt bis nach der Abgabe verborgen.</span></label><textarea id="testAnswer" class="free-answer-input" maxlength="6000" rows="8" aria-describedby="testAnswerCount" placeholder="${isVisual?'Beschreibe die Bauteile und Zusammenhänge. Deine Zeichnung kannst du daneben auf Papier anfertigen …':'Erkläre, was du verstanden hast. Stichpunkte und Beispiele sind möglich …'}">${esc(entry.answer)}</textarea><div class="writing-footer"><span id="testAnswerCount">${entry.answer.length} / 6.000 Zeichen</span><span>Auf diesem Gerät gespeichert.</span></div><div class="test-question-grid" aria-label="Testfragen auswählen">${t.ids.map((q,i)=>button('test-position',`${i+1}${t.entries[q].answer.trim()?' ✓':''}`,'test-question-number '+(i===t.position?'active':''),`data-position="${i}" aria-label="Testfrage ${i+1}${t.entries[q].answer.trim()?', beantwortet':''}" ${i===t.position?'aria-current="true"':''}`)).join('')}</div></article><div class="unit-reading-footer">${button('test-prev',icon('back')+' Zurück','button secondary',t.position===0?'disabled':'')}${t.position<t.ids.length-1?button('test-next','Nächste Frage '+icon('arrow'),'button primary'):button('test-submit','Test abgeben '+icon('check'),'button primary')}</div>${t.position<t.ids.length-1?`<div class="test-submit-early">${button('test-submit','Test jetzt abgeben','text-link')}</div>`:''}<p class="ai-disclosure">Nach Abgabe werden nur Textfragen an Google Gemini gesendet. Bild- und Skizzenfragen vergleichst du selbst mit der Vorlage. Du kannst jederzeit über „Speichern & zurück“ pausieren. Leere Textantworten werden als noch zu üben gesammelt.</p>`;
    }
    return `${top}<section class="panel test-result-overview"><div class="eyebrow">${t.status==='complete'?'DEIN TEST IST AUSGEWERTET':'DEINE ANTWORTEN SIND ABGEGEBEN'}</div><h1>${t.status==='complete'?'Aus Antworten wird <em>Fortschritt.</em>':'Dein Test bleibt <em>gespeichert.</em>'}</h1><p>${s.pending?`${s.total-s.pending} von ${s.total} Fragen ausgewertet. ${manualPending?manualPending+' '+(manualPending===1?'Frage wartet':'Fragen warten')+' auf deinen eigenen Vergleich.':''}`:`${s.correct} von ${s.total} ${s.total===1?'Frage':'Fragen'} als sicher / richtig eingeschätzt. Fehler und Unsicherheiten kommen in spätere Tests zurück.`}</p><div class="test-result-counts">${[['correct',s.correct,'Richtig / sicher'],['partial',s.partial,'Teilweise'],['incorrect',s.incorrect,'Noch üben'],['unclear',s.unclear,'Nachprüfen']].map(([cls,n,label])=>`<div class="${cls}"><b>${n}</b><span>${label}</span></div>`).join('')}</div>${s.points?`<p class="test-points"><b>${s.percent}%</b> der automatisch bewerteten Text-Fachpunkte erfüllt · ${s.approved} / ${s.points} Punkte</p>`:''}${s.manual?`<p class="small-muted">${s.manual} ${s.manual===1?'Frage wurde':'Fragen wurden'} von dir selbst eingeschätzt; sie sind nicht Teil der KI-Punktzahl.</p>`:''}${busy?`<div class="grading-progress" role="status"><span class="loading-dot"></span> Textbewertung läuft. Bereits bewertete Fragen werden gespeichert.</div>`:textPending?button('test-grade','Textbewertung fortsetzen '+icon('spark'),'button primary'):''}${manualPending?'<div class="visual-note"><b>Dein eigener Vergleich ist noch offen</b><span>Öffne unten die Fragen, vergleiche mit der Vorlage und wähle „Noch üben“, „Unsicher“ oder „Sicher erinnert“.</span></div>':''}${error?`<div class="notice warning" role="alert">${esc(error)}</div>`:''}${!ai.configured&&textPending?'<p class="ai-disclosure">Für die Textbewertung ist eine eingerichtete Gemini-Anbindung erforderlich.</p>':''}<small>Lernfeedback und Selbsteinschätzung, keine offizielle Prüfungsnote.</small></section><div class="test-result-list">${t.ids.map((id,i)=>{const card=byId(id),e=t.entries[id],a=e.assessment,isVisual=visual(card),pendingVisual=(isVisual||!ai.configured)&&!a;return `<details class="panel test-result-item" ${pendingVisual?'open':''}><summary><span class="case-id">${id}</span><span><strong>${i+1}. ${esc(card.title)}</strong><small>${a?(a.manualVisual||a.manualSelf?'Eigener Vergleich · ':'')+labels[a.verdict]:isVisual?'Bild / Skizze · selbst vergleichen':!ai.configured?'Ohne API · selbst vergleichen':'Textbewertung ausstehend'}${e.source==='repeat'?' · Wiederholung':e.source==='control'?' · Kontrollfrage':''}</small></span><span class="result-indicator ${a?.verdict||'pending'}">${icon(a?.verdict==='correct'?'check':a?'learn':'clock')}</span></summary><div class="test-detail"><p class="study-question">${esc(card.question)}</p><h3>Deine abgegebene Antwort</h3><p class="answer-verbatim">${esc(e.answer)||'Keine Textantwort abgegeben.'}</p>${pendingVisual?`${isVisual?(Q?.visualNote(card)||''):'<div class="visual-note"><b>Ohne API · dein eigener Vergleich</b><span>Lies deine Antwort, decke dann die Fachpunkte auf und schätze deinen Wissensstand ehrlich ein. Keine KI-Bewertung.</span></div>'}<div class="recall-drawing">${isVisual?drawings(card):''}</div>${Q?Q.gallery(Q.entry(state||{},id)):''}<details class="test-reference"><summary>Vorlage und Fachpunkte zum Vergleich öffnen</summary>${answerHTML(card)}</details><div class="visual-grade-buttons">${[['again','Noch üben'],['hard','Unsicher'],['good','Sicher erinnert']].map(([grade,label])=>button('self-grade',label,'button '+(grade==='good'?'primary':'secondary'),`data-id="${id}" data-grade="${grade}" ${busy?'disabled':''}`)).join('')}</div>`:a?root.LernpassWriter.feedback(a):'<p>Diese Textantwort wartet noch auf die Bewertung.</p>'}${a?`<details class="test-reference"><summary>Erklärung und Fachpunkte nachlesen</summary>${answerHTML(card)}</details>`:''}</div></details>`;}).join('')}</div><div class="button-row">${button('flow-hub','Zur Lernübersicht '+icon('arrow'),'button primary')}${t.status==='complete'?button('unit-start','Neue Lerneinheit','button secondary'):''}</div>`;
  }
  const api={hub,unitPage,testPage};root.LernpassUnitUI=api;if(typeof module!=='undefined'&&module.exports)module.exports=api;
})(typeof window!=='undefined'?window:globalThis);
